// Every picture is a circle 100 units wide with a little round window (its portal) that holds the next picture.
// Four pictures make a pack, and the fourth one's window holds the first again, so you can zoom in or out forever.
// PACKS comes from packs.js (generated by sync-art.js from the app's art source).
"use strict";

